#include <stdio.h>

int main(void) {
    int N, T;
    scanf("%d %d", &N, &T);

    long long ans = 0;

    if (T == 0) {
        ans = N;
    } else if (T == 1) {
        ans = (long long)N * (N - 1);
    } else if (T == 2) {
        if (N >= 3) {
            ans = (long long)N * (N - 1) * (N - 2) / 6;
        }
    }

    printf("%lld\n", ans);
    return 0;
}
